export const simulateLogin = (credentials) => {
    return new Promise((resolve, reject) => {
        setTimeout(() => {
            if (credentials.username === "admin" && credentials.password === "admin") {
                resolve("fake-token-" + Date.now());
            }
            else {
                reject(new Error("Неверный логин или пароль"));
            }
        }, 2000);
    });
};
