import { apiInstance } from "@/shared/api";
export const getUsers = () => apiInstance.get("/users").then((res) => res.data);
export const getUserById = (id) => apiInstance.get(`/users/${id}`).then((res) => res.data);
export const createUser = (data) => apiInstance.post("/users", data).then((res) => res.data);
export const updateUser = (id, data) => apiInstance.put(`/users/${id}`, data).then((res) => res.data);
export const deleteUser = (id) => apiInstance.delete(`/users/${id}`);
